-- Mes liens actuels (iClosed) repris dans Calio : même nom, même fin de lien → rdv.theambitiousman.fr/e/<lien>.
-- Les hôtes Amandine / Clément deviennent la priorité « haute » ; les événements sans closer (setting Ismael / Jérémy) ou désactivés sur iClosed sont importés désactivés.
alter table public.cand_events add column if not exists notes text;
alter table public.cand_events drop constraint if exists cand_events_slug_check;
alter table public.cand_events add constraint cand_events_slug_check check (slug is null or slug ~ '^[a-z0-9][a-z0-9-]{1,59}$');
on conflict (slug) do nothing;
